def check_T(m):
    # T = m(m+1)/6
    if m <= 0:
        return False, 0

    numerator = m * (m + 1)

    if numerator % 6 == 0:
        T = numerator // 6
        return True, T
    else:
        return False, 0

solutions_m = []
for m in range(1, 101):
    is_valid, T = check_T(m)
    if is_valid:
        solutions_m.append(m)

print("Values of m (up to 100) for which T is an integer:")
print(solutions_m)

